// Original source and component/project API bytes from the Salesforce-admitted packet.
func TestRunInheritedSchedulerStaticAdmitted(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/BaseScheduler.cls"), "public virtual class BaseScheduler {\npublic static Boolean testShouldSchedule=false;\npublic static Set<Type> typesAlreadyScheduledFor=new Set<Type>();\npublic void ensureScheduled(){\nif (testShouldSchedule && !typesAlreadyScheduledFor.contains(ChildScheduler.class)) {\n\ttypesAlreadyScheduledFor.add(ChildScheduler.class);\n\tSystem.enqueueJob(new QueueWorker());\n}\n}\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/BaseScheduler.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/ChildScheduler.cls"), "public class ChildScheduler extends BaseScheduler {}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/ChildScheduler.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/ParentBatch.cls"), "public class ParentBatch implements Database.Batchable<SObject> {\npublic Iterable<SObject> start(Database.BatchableContext context){return new List<SObject>();}\npublic void execute(Database.BatchableContext context,List<SObject> scope){}\npublic void finish(Database.BatchableContext context){new ChildScheduler().ensureScheduled();}\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/ParentBatch.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/QueueWorker.cls"), "public class QueueWorker implements Queueable {\npublic void execute(QueueableContext context){Database.executeBatch(new FollowupBatch(), 200);}\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/QueueWorker.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/FollowupBatch.cls"), "public class FollowupBatch implements Database.Batchable<SObject> {\npublic Iterable<SObject> start(Database.BatchableContext context){return new List<SObject>();}\npublic void execute(Database.BatchableContext context,List<SObject> scope){}\npublic void finish(Database.BatchableContext context){}\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/FollowupBatch.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeInheritedAsyncCountProbe67.cls"), "@IsTest private class GladeInheritedAsyncCountProbe67 {\n@IsTest static void inheritedSchedulerRetainsOriginalFourJobAssertion(){\nBaseScheduler.testShouldSchedule = true;\nnew ChildScheduler().ensureScheduled();\nTest.startTest();\nDatabase.executeBatch(new ParentBatch(), 200);\nTest.stopTest();\nList<AsyncApexJob> allJobs=[SELECT Id,ApexClass.Name,JobType,Status,ParentJobId,JobItemsProcessed,TotalJobItems,NumberOfErrors,ExtendedStatus,CompletedDate FROM AsyncApexJob];\nMap<Id,AsyncApexJob> byId=new Map<Id,AsyncApexJob>(allJobs);\nList<String> jobRows=new List<String>();\nfor(AsyncApexJob job:allJobs){\n AsyncApexJob parent=byId.get(job.ParentJobId);\n jobRows.add(JSON.serialize(new List<Object>{job.ApexClass.Name,job.JobType,job.Status,job.ParentJobId!=null,parent==null?null:parent.ApexClass.Name,parent==null?null:parent.JobType,job.JobItemsProcessed,job.TotalJobItems,job.NumberOfErrors,job.ExtendedStatus,job.CompletedDate!=null}));\n}\njobRows.sort();\nMap<String,Object> observed=new Map<String,Object>{'jobCount'=>allJobs.size(),'jobs'=>jobRows,'staticTestShouldSchedule'=>BaseScheduler.testShouldSchedule,'staticSetIsNull'=>BaseScheduler.typesAlreadyScheduledFor==null};\nif(BaseScheduler.typesAlreadyScheduledFor!=null){\n List<String> types=new List<String>();for(Type item:BaseScheduler.typesAlreadyScheduledFor)types.add(String.valueOf(item));types.sort();\n observed.put('staticSetSize',BaseScheduler.typesAlreadyScheduledFor.size());observed.put('staticSetTypes',types);observed.put('staticContainsChild',BaseScheduler.typesAlreadyScheduledFor.contains(ChildScheduler.class));\n}\nSystem.assertEquals(allJobs.size(),jobRows.size(),'Every visible job retained');\nString payload=JSON.serialize(observed);System.assert(payload.length()<2900,'Inherited observation exceeds bound');\nMap<String,Object> expected=new Map<String,Object>{'staticContainsChild'=>true,'staticSetTypes'=>new List<String>{'ChildScheduler'},'staticSetSize'=>1,'staticSetIsNull'=>false,'staticTestShouldSchedule'=>true,'jobs'=>new List<String>{'[\"FollowupBatch\",\"BatchApex\",\"Completed\",false,null,null,0,0,0,null,true]','[\"ParentBatch\",\"BatchApex\",\"Completed\",false,null,null,0,0,0,null,true]','[\"QueueWorker\",\"Queueable\",\"Completed\",false,null,null,0,0,0,null,true]'},'jobCount'=>3};\nSystem.assertEquals(expected.keySet(),observed.keySet(),'Exact inherited observation fields');\nfor(String field:expected.keySet()){\n if(field=='jobs'||field=='staticSetTypes'){\n  List<String> want=(List<String>)expected.get(field);List<String> actual=(List<String>)observed.get(field);\n  System.assertEquals(want.size(),actual.size(),'Exact inherited list size '+field);\n  for(Integer index=0;index<want.size();index++)System.assertEquals(want[index],actual[index],'Exact inherited '+field+' row '+index);\n }else{System.assertEquals(expected.get(field),observed.get(field),'Exact inherited '+field);}\n}\n}\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeInheritedAsyncCountProbe67.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>67.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\": \"67.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 1 || got.Passed != 1 || got.Failed != 0 || got.Errors != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("Admitted static lifecycle failed: %s", data)
	}
}

// Original source and component/project API bytes from the Salesforce-admitted packet.
func TestRunFutureQueryCacheStaticAdmitted(t *testing.T) {
	root := t.TempDir()
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeRollupCache53.cls"), "public class GladeRollupCache53 {\n public static Map<String,String> fieldByObject;\n public static String queryCache;\n public static String queryFor(String field){\n  if(fieldByObject==null)fieldByObject=new Map<String,String>{'Account'=>field};\n  if(queryCache==null)queryCache='SELECT Id,'+fieldByObject.get('Account')+' FROM Account WHERE Id=:targetId';\n  return queryCache;\n }\n @future public static void run(Id targetId){\n  Account configuration=[SELECT Description FROM Account WHERE Id=:targetId];\n  Map<String,Object> observed=new Map<String,Object>{'mapWasNull'=>fieldByObject==null,'queryWasNull'=>queryCache==null};\n  String query=queryFor(configuration.Description);\n  observed.put('mappedField',fieldByObject.get('Account'));observed.put('query',query);\n  try{Account result=Database.query(query);observed.put('value',result.get(configuration.Description));observed.put('returned',true);}\n  catch(Exception e){observed.put('returned',false);observed.put('type',e.getTypeName());observed.put('message',e.getMessage());}\n  update new Account(Id=targetId,Description=JSON.serialize(observed));\n }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeRollupCache53.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>53.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeRollupCacheObserve53.cls"), "@IsTest private class GladeRollupCacheObserve53 {\n private static void run(Boolean warm){\n  Account row=new Account(Name='owned-old-name',Phone='owned-phone',Description='Phone');insert row;\n  if(warm)GladeRollupCache53.queryFor('Name');\n  Map<String,Object> observed=new Map<String,Object>{'warm'=>warm,'callerMapBeforeNull'=>GladeRollupCache53.fieldByObject==null,'callerQueryBefore'=>GladeRollupCache53.queryCache};\n  Test.startTest();GladeRollupCache53.run(row.Id);Test.stopTest();\n  observed.put('callerMapAfterNull',GladeRollupCache53.fieldByObject==null);observed.put('callerQueryAfter',GladeRollupCache53.queryCache);\n  observed.put('future',JSON.deserializeUntyped([SELECT Description FROM Account WHERE Id=:row.Id].Description));\n  String text=JSON.serialize(observed);System.assert(text.length()<2900,'Owned cache observation exceeds bound');verify(observed,warm);\n }\n @IsTest static void futureWithWarmQueryCache(){run(true);}\n @IsTest static void futureWithColdQueryCache(){run(false);}\n private static void verify(Map<String,Object> observed, Boolean warm){\n  Map<String,Object> expected=(Map<String,Object>)JSON.deserializeUntyped(warm ? '{\"warm\":true,\"callerMapBeforeNull\":false,\"callerQueryBefore\":\"SELECT Id,Name FROM Account WHERE Id=:targetId\",\"callerMapAfterNull\":false,\"callerQueryAfter\":\"SELECT Id,Name FROM Account WHERE Id=:targetId\",\"future\":{\"mapWasNull\":false,\"queryWasNull\":false,\"mappedField\":\"Name\",\"query\":\"SELECT Id,Name FROM Account WHERE Id=:targetId\",\"returned\":false,\"type\":\"System.SObjectException\",\"message\":\"SObject row was retrieved via SOQL without querying the requested field: Account.Phone\"}}' : '{\"warm\":false,\"callerMapBeforeNull\":true,\"callerQueryBefore\":null,\"callerMapAfterNull\":false,\"callerQueryAfter\":\"SELECT Id,Phone FROM Account WHERE Id=:targetId\",\"future\":{\"mapWasNull\":true,\"queryWasNull\":true,\"mappedField\":\"Phone\",\"query\":\"SELECT Id,Phone FROM Account WHERE Id=:targetId\",\"value\":\"owned-phone\",\"returned\":true}}');\n  System.assertEquals(expected.keySet(),observed.keySet(),'complete outer fields');\n  for(String key:expected.keySet()){\n   if(key=='future'){\n    Map<String,Object> expectedFuture=(Map<String,Object>)expected.get(key);\n    Map<String,Object> actualFuture=(Map<String,Object>)observed.get(key);\n    System.assertEquals(expectedFuture.keySet(),actualFuture.keySet(),'complete future fields');\n    for(String futureKey:expectedFuture.keySet())System.assertEquals(expectedFuture.get(futureKey),actualFuture.get(futureKey),'future.'+futureKey);\n   }else System.assertEquals(expected.get(key),observed.get(key),key);\n  }\n }\n}\n")
	writeFile(t, filepath.Join(root, "force-app/main/default/classes/GladeRollupCacheObserve53.cls-meta.xml"), "<ApexClass xmlns=\"http://soap.sforce.com/2006/04/metadata\"><apiVersion>53.0</apiVersion><status>Active</status></ApexClass>\n")
	writeFile(t, filepath.Join(root, "sfdx-project.json"), "{\"sourceApiVersion\": \"53.0\", \"packageDirectories\": [{\"path\": \"force-app\", \"default\": true}]}")
	run := Run(loadTestIndex(t, root), Options{})
	if got := run.Summary(); got.Total != 2 || got.Passed != 2 || got.Failed != 0 || got.Errors != 0 {
		data, _ := json.Marshal(run)
		t.Fatalf("Admitted static lifecycle failed: %s", data)
	}
}
